"Deckkraft der Fenster":"Logu necaurredzamība",
"Den Schlüssel wie ein Kennwort behandeln: Wer ihn hat und auf diesem Rechner läuft, kann den geöffneten Entwurf ändern. Der Anschluss bleibt nur offen, solange WerkFab läuft.":"Izturieties pret atslēgu kā pret paroli: kam tā ir un kas darbojas šajā datorā, var mainīt atvērto projektu. Ports paliek atvērts tikai tik ilgi, kamēr darbojas WerkFab.",
"Der Anschluss antwortet nicht.":"Ports neatbild.",
"Der Durchmesser ist kleiner als die doppelte Wanddicke":"Diametrs ir mazāks par divkāršu sienas biezumu",
"Der Durchmesser würde null oder negativ – Abstand verkleinern":"Diametrs kļūtu nulle vai negatīvs – samaziniet attālumu",
"Der Geometriekern konnte dieses Feature nicht berechnen – Maße und gewählte Kanten oder Flächen prüfen.":"Ģeometrijas kodols nevarēja aprēķināt šo elementu – pārbaudiet izmērus un izvēlētās malas vai virsmas.",
"Der Gewindefräser läuft im vollen Material: Den Zapfen vorher freifräsen (2D-Kontur außen um den Zapfen bis zur Gewindetiefe).":"Vītņu frēze strādā pilnā materiālā: iepriekš izfrēzējiet tapu (2D kontūra ārpus tapas līdz vītnes dziļumam).",
"Der Körper hat auf dieser Ebene keinen Umriss.":"Ķermenim šajā plaknē nav apriša.",
"Der Körper hat keine ebene Fläche":"Ķermenim nav plakanas skaldnes",
"Der Körper ist zu dick für ein Blech":"Ķermenis ir pārāk biezs skārdam",
"Der Körper muss überall gleich dick sein – gezeichnet, extrudiert oder aus einer STEP-Datei. Erkannt werden die Blechdicke (Abstand der größten Fläche zu ihrer Gegenfläche), die ebenen Wände und die Biegungen dazwischen mit Winkel und Innenradius, rund oder scharfkantig. Daraus entsteht die Abwicklung; als Blech liegt sie als Skizze mit Biegelinien vor und lässt sich wie jedes Blech ändern, abwickeln und schachteln. Der K-Faktor bestimmt die gestreckten Längen. Zeigt die größte Fläche nach oben oder unten, liegt das Blech genau im Körper, sonst flach auf der XY-Ebene. Säume (180°) und gerundete Wände zwischen zwei ebenen Wänden werden als Biegung mit eigenem Radius übernommen. Nicht erkannt werden frei endende gerollte Ränder, Rohre und Umformungen wie Sicken.":"Ķermenim visur jābūt vienāda biezuma – uzzīmētam, izspiestam vai no STEP faila. Tiek atpazīts skārda biezums (lielākās skaldnes attālums līdz tai pretējai skaldnei), plakanās sienas un starp tām esošās lieces ar leņķi un iekšējo rādiusu, noapaļotas vai asām malām. No tā rodas izklājums; kā skārds tas ir skice ar lieces līnijām, un to var mainīt, izklāt un izvietot kā jebkuru skārdu. K-faktors nosaka izklāto garumus. Ja lielākā skaldne vērsta uz augšu vai uz leju, skārds atrodas tieši ķermenī, citādi plakaniski XY plaknē. Malas locījumi (180°) un noapaļotas sienas starp divām plakanām sienām tiek pārņemtas kā liece ar savu rādiusu. Netiek atpazītas brīvi beidzošās velmētās malas, caurules un formējumi, piemēram, ribas.",
"Der Körper wird mit den Dreiecken der Anzeige als Netz übernommen. Er selbst bleibt erhalten; spätere Änderungen am Körper ändern das Netz nicht.":"Ķermenis tiek pārņemts kā tīkls ar attēlojuma trijstūriem. Pats ķermenis tiek saglabāts; vēlākas ķermeņa izmaiņas tīklu nemaina.",
"Der Körper wird um seine senkrechte Mittelachse abgetastet und als Halterkontur (Abschnitte) in der Dokument-Werkzeugbibliothek gespeichert.":"Ķermenis tiek nolasīts ap savu vertikālo centra asi un saglabāts kā turētāja kontūra (posmi) dokumenta instrumentu bibliotēkā.",
"Der Nahtspalt ist größer als der Umfang":"Šuves sprauga ir lielāka par apkārtmēru",
"Der Punkt, um den sich die Ansicht dreht (bei freiem Orbit). „Unter dem Mauszeiger“: die Stelle des Modells, an der die Drehung beginnt.":"Punkts, ap kuru griežas skats (brīvā orbītā). „Zem peles kursora”: modeļa vieta, kurā sākas griešana.",
"Der Radius wächst gleichmäßig vom Anfang zum Ende jeder gewählten Kante. Welches Ende der Anfang ist, legt die Kante fest – bei Bedarf tauschen.":"Rādiuss vienmērīgi pieaug no katras izvēlētās malas sākuma līdz beigām. Kurš gals ir sākums, nosaka mala – vajadzības gadījumā apmainiet.",
"Der Rand einer Fläche ist eine geschlossene Kette: Mit „durchlaufend“ läuft der Radius einmal ringsum, ohne diese Option auf jeder Kante für sich vom Anfangs- zum Endradius.":"Skaldnes mala ir slēgta ķēde: ar „nepārtraukti“ rādiuss iet vienreiz visapkārt, bez šīs opcijas uz katras malas atsevišķi no sākuma līdz beigu rādiusam.",
"Der Schnitt trifft keinen Körper – es wird kein Material entfernt.":"Griezums netrāpa nevienam ķermenim – materiāls netiek noņemts.",
"Der Text steht als Kommentar an dieser Stelle im Programm.":"Teksts programmā šajā vietā tiek ierakstīts kā komentārs.",
"Der alte Schlüssel gilt dann nicht mehr; verbundene Agenten müssen neu eingerichtet werden":"Vecā atslēga tad vairs nav derīga; pievienotie aģenti jāiestata no jauna",
"Der erste Abstand wird auf der Fläche gemessen, die mehr nach oben (Z) zeigt, der zweite Abstand bzw. der Winkel gilt zur anderen Fläche. „Seiten tauschen“ kehrt das um. Tangential anschließende Kanten laufen mit.":"Pirmais attālums tiek mērīts uz skaldnes, kas vairāk vērsta uz augšu (Z), otrais attālums vai leņķis attiecas uz otru skaldni. „Apmainīt puses“ to apgriež. Tangenciāli pieslēdzošās malas tiek iekļautas.",
"Der gewählte Körper ist das Rohteil (z. B. ein Guss- oder Schmiederohling). Er wird selbst nicht bearbeitet.":"Izvēlētais ķermenis ir sagatave (piem., lējuma vai kaluma sagatave). Pats tas netiek apstrādāts.",
"Der große Geometriekern ist noch nicht geladen":"Pilnais ģeometrijas kodols vēl nav ielādēts",
"Der große Geometriekern wird geladen – dieser Schritt rechnet gleich von selbst nach":"Lielais ģeometrijas kodols tiek ielādēts – šis solis drīz pārrēķināsies pats",
"Design":"Noformējums",
"Design als Datei":"Dizains failā",
"Design exportiert":"Dizains eksportēts",
"Design geladen – mit „Übernehmen“ wird es wirksam.":"Dizains ielādēts – ar „Lietot“ tas stāsies spēkā.",
"Design nicht gefunden.":"Dizains nav atrasts.",
"Design, Farben, Symbole, Form und Schrift in einer Datei – zum Weitergeben oder für einen anderen Rechner":"Dizains, krāsas, simboli, forma un burti vienā failā – nodošanai tālāk vai citam datoram",
"Designs suchen":"Meklēt dizainus",
