"Drehen: Elemente wählen, dann Drehpunkt anklicken und den Winkel mit der Maus zeigen (Vorschau); auch als Kopie":"Pagriezt: izvēlieties elementus, pēc tam noklikšķiniet uz griešanās punkta un ar peli norādiet leņķi (priekšskatījums); arī kā kopiju",
