"Durchzug {0}: zu hoch für diese Bohrung (die Vorbohrung bliebe ohne Durchmesser)":"Atveres apmale {0}: pārāk augsta šim caurumam (iepriekšējam urbumam nepaliktu diametra)",
"Durchzug: der Rand einer runden Bohrung wird zu einem Kragen hochgezogen, etwa als Gewindedurchzug. Der Bohrungsdurchmesser der Skizze ist der fertige Innendurchmesser; im Zuschnitt wird die kleinere Vorbohrung geschnitten.":"Atveres apmale: apaļa cauruma mala tiek izvilkta uz augšu par apmali, piemēram, kā vītnes apmale. Skices cauruma diametrs ir gatavais iekšējais diametrs; sagatavē tiek izgriezts mazāks iepriekšējais urbums.",
