"Ein eingefügter Satz verschiebt alle folgenden Satznummern – so zählen sie nicht als Änderung":"Ievietots bloks nobīda visus nākamos bloku numurus – tā tie netiek uzskatīti par izmaiņām",
"Ein gerollter Rand über 350° schließt sich zum Rohr – das ist so nicht herstellbar":"Velmēta mala virs 350° noslēdzas par cauruli – tā to nevar izgatavot",
"Ein geschlossenes Netz in einen Volumenkörper umwandeln (jedes Dreieck wird eine Fläche)":"Pārveidot slēgtu tīklu par tilpuma ķermeni (katrs trijstūris kļūst par skaldni)",
"Ein runder Fräser lässt in jeder Innenecke seinen Radius stehen – ein eckiges Gegenstück passt dann nicht hinein. Der Freistich fährt an jeder scharfen Innenecke kurz in die Ecke und zurück.{0}{1}":"Apaļa frēze katrā iekšējā stūrī atstāj savu rādiusu – stūrains pretdetaļas elements tad neiekļaujas. Izgriezums pie katra asā iekšējā stūra īsi ieiet stūrī un atpakaļ.{0}{1}",
"Ein verbundener Agent arbeitet am geöffneten Entwurf: Er liest und ändert die Zeitachse, fragt Körper, Volumen und Fehler ab, holt Normteile aus dem Bauteilkatalog, lässt sich ein Bild der Ansicht geben, exportiert STEP oder STL, legt Werkzeuge und Fertigungsoperationen an und gibt das NC-Programm aus – das vor dem ersten Schnitt zu prüfen bleibt. Auf Dateien, Einstellungen und andere Entwürfe hat er keinen Zugriff. Jede Änderung ist ein Schritt, den Strg+Z zurücknimmt.":"Pievienotais aģents strādā ar atvērto projektu: tas lasa un maina laika joslu, vaicā ķermeņus, tilpumu un kļūdas, ņem standarta detaļas no detaļu kataloga, saņem skata attēlu, eksportē STEP vai STL, izveido instrumentus un ražošanas operācijas un izvada NC programmu – kas pirms pirmā griezuma joprojām jāpārbauda. Tam nav piekļuves failiem, iestatījumiem un citiem projektiem. Katra izmaiņa ir viens solis, ko Ctrl+Z atsauc.",
"Ein zweiter Klick auf die Schaltfläche des Zeichenwerkzeugs schaltet zurück auf Auswählen":"Otrs klikšķis uz zīmēšanas rīka pogas pārslēdz atpakaļ uz Atlasīt",
