"Fläche anklicken – die Bohrung entsteht mit":"Noklikšķiniet uz virsmas – caurums rodas vienlaikus",
"Fläche anklicken: an jedem Klickpunkt entsteht die Durchgangsbohrung für die Schraube (ISO 273, Reihe mittel) durch alle Teile, die dort aufeinanderliegen – für Senkschrauben mit 90°-Senkung, für Zylinderschrauben auf Wunsch mit Senkbohrung (DIN 974-1, Reihe 1) so tief wie der Kopf. Die Schraube sitzt gleich darin. Bohrung und Schraube lassen sich danach im Verlauf ändern.":"Noklikšķiniet uz virsmas: katrā klikšķa punktā rodas caurejošs caurums skrūvei (ISO 273, vidējā sērija) cauri visām detaļām, kas tur atrodas viena uz otras – skrūvēm ar slēpto galvu ar 90° konisko izurbumu, cilindriskās galvas skrūvēm pēc izvēles ar cilindrisko izurbumu (DIN 974-1, 1. sērija) galvas dziļumā. Skrūve uzreiz ir caurumā. Caurumu un skrūvi pēc tam var mainīt laika joslā.",
"Fläche eines Körpers anklicken: ihr Rand kommt als Kontur in die Skizze. Eine Kante anklicken projiziert nur diese Kante (Kreise bleiben Kreise). Projizierte Geometrie ist violett.":"Noklikšķiniet uz ķermeņa skaldnes: tās mala tiek pievienota skicei kā kontūra. Klikšķis uz malas projicē tikai šo malu (riņķi paliek riņķi). Projicētā ģeometrija ir violeta.",
