"Fusion-360-Dateien (.f3d) sind ein geschlossenes Autodesk-Format und können nicht gelesen werden.\n\nIn Fusion 360: Datei → Exportieren → STEP (.stp) wählen und diese Datei hier importieren.":"Fusion 360 faili (.f3d) ir slēgts Autodesk formāts, un tos nevar nolasīt.\n\nProgrammā Fusion 360: izvēlieties Fails → Eksportēt → STEP (.stp) un importējiet šo failu šeit.",
