"Für V-Gravur einen Fasenfräser (V) wählen":"V-gravēšanai izvēlieties nošķēlumu frēzi (V)",
"Für den Steuerungszyklus entlang einer Linie die Nutbreite angeben":"Vadības ciklam gar līniju norādiet rievas platumu",
