"Für schräge Richtungen eine Konstruktionsachse anlegen (durch zwei Punkte, einen Zylinder oder zwei Ebenen) – sie erscheint dann hier als Richtung.":"Slīpiem virzieniem izveidojiet konstrukcijas asi (caur diviem punktiem, cilindru vai divām plaknēm) – tā tad parādīsies šeit kā virziens.",
