"Gemeinsame Schnittkanten nur einmal schneiden":"Kopīgās griezuma malas griezt tikai vienreiz",
"Gemeinsame Schnittkanten: liegen zwei Zuschnitte genau eine Schnittfuge auseinander (beim Schachteln als Abstand die Schnittfuge eintragen), fällt ihre Bahn auf der gemeinsamen Kante zusammen und wird nur einmal geschnitten. Der Anschnitt liegt nie in einem Nachbarteil: ist neben einer Kontur kein freier Abfall, wird auf der Kontur eingestochen. Nach „Vorschau“ zeigt ein Bild je Tafel die Bahn, bevor die Dateien gespeichert werden.":"Kopīgās griezuma malas: ja divi izgriezumi atrodas tieši vienas griezuma platuma attālumā (izkārtojot kā attālumu ievadiet griezuma platumu), to trajektorija uz kopīgās malas sakrīt un tiek griezta tikai vienreiz. Iegriešanās nekad neatrodas blakus detaļā: ja blakus kontūrai nav brīvu atlikumu, caurduršana notiek uz kontūras. Pēc „Priekšskatījuma” viens attēls katrai loksnei parāda trajektoriju pirms failu saglabāšanas.",
