"Geschlossen":"Slēgts",
"Geschlossen (Gehrung)":"Slēgts (stūrsavienojums)",
"Geschlossen: Laschen an zwei Nachbarkanten laufen bis zur Winkelhalbierenden der Ecke und lassen dort den Spalt frei. Die Eckfreistellung sitzt, wo sich die Biegezonen kreuzen – in der Abwicklung und im gebogenen Teil. Auch eine Lasche an einer gebogenen Kante wird an einer echten Ecke auf Gehrung geschnitten (dort ohne Eckfreistellung).":"Slēgts: atloki uz divām blakus esošām malām iet līdz stūra bisektrisei un atstāj tur spraugu. Stūra atbrīvojums atrodas tur, kur krustojas liekuma zonas – izklājumā un saliektajā detaļā. Arī atloks uz izliektas malas īstā stūrī tiek griezts slīpi (tur bez stūra atbrīvojuma).",
"Geschlossene Kette {0}":"Slēgta ķēde {0}",
"Geschlossene Profile begrenzen den Bereich.":"Slēgti profili ierobežo apgabalu.",
"Geschlossene Profile der aktiven Skizze farbig füllen":"Aizpildīt aktīvās skices slēgtos profilus ar krāsu",
"Geschlossene Profile werden zu ebenen Flächen – z. B. Deckel und Boden, um Flächen anschließend zu einem Körper zusammenzufügen.":"Slēgti profili kļūst par plakanām virsmām – piem., vāks un dibens, lai virsmas pēc tam sašūtu ķermenī.",
"Geschnitten ab X":"Griezts no X",
"Geschwenkte Bearbeitungsebene":"Sagāzta apstrādes plakne",
"Geschwindigkeit der Animation":"Animācijas ātrums",
"Geschätzte Bearbeitungszeit (Klick: Details)":"Aptuvenais apstrādes laiks (klikšķis: sīkāka informācija)",
"Gesicherte Vorgaben laden":"Ielādēt saglabātos noklusējumus",
"Gespeichert unter neuem Namen":"Saglabāts ar jaunu nosaukumu",
"Gespeichert werden Blechdicke {0} mm, Biegeradius innen {1} mm und K-Faktor {2}. Die Regel steht danach bei jedem Blech in der Liste „Blechregel“ – auch in anderen Projekten auf diesem Rechner.":"Tiks saglabāts skārda biezums {0} mm, iekšējais lieces rādiuss {1} mm un K-faktors {2}. Pēc tam likums būs sarakstā „Skārda likums“ pie katra skārda – arī citos projektos šajā datorā.",
"Gespiegelt":"Spoguļots",
"Gestrichelt im DXF/der Skizze: Biegelinien (Anfang und Ende jeder Biegezone). Im DXF liegen sie auf der Ebene BIEGUNG, der Umriss auf Ebene 0.":"Pārtraukta līnija DXF/skicē: locījuma līnijas (katras locījuma zonas sākums un beigas). DXF tās atrodas slānī BIEGUNG, kontūra – slānī 0.",
