"Gewindebohrung":"Vītņots caurums",
"Gewindebohrung M6":"Vītņots urbums M6",
"Gewindebohrung für {0}":"Vītņots caurums priekš {0}",
"Gewindebohrung für {0} – Skizze":"Vītņots caurums priekš {0} – skice",
"Gewindebohrung im untersten Teil":"Vītņots caurums apakšējā detaļā",
"Gewindebohrung im untersten Teil: die Durchgangsbohrung endet, wo das unterste Teil beginnt; dort entsteht das Kernloch mit Gewinde – drei Gewindegänge tiefer, als die Schraube reicht, oder durch das ganze Teil. Liegt nur ein Teil unter dem Punkt, bekommt es das Gewinde von der Fläche an. „Länge passend zur Einschraubtiefe“ nimmt die nächste Länge der Reihe, mit der die Schraube etwa so tief im Gewinde sitzt, wie ihr Gewinde dick ist (Richtwert für Stahl) – aber nie länger, als das Teil dick ist.":"Vītnes caurums apakšējā detaļā: caurejošais caurums beidzas tur, kur sākas apakšējā detaļa; tur rodas serdes caurums ar vītni – trīs vītnes pagriezienus dziļāk, nekā skrūve sniedzas, vai cauri visai detaļai. Ja zem punkta ir tikai viena detaļa, tā vītni saņem no skaldnes. „Garums atbilstoši ieskrūvēšanas dziļumam“ ņem nākamo garumu no rindas, ar kuru skrūve vītnē sēž aptuveni tik dziļi, cik resna ir tās vītne (orientējoša vērtība tēraudam) – bet nekad ne garāku, nekā detaļa ir bieza.",
"Gewindebohrung {0} – Einschraubtiefe nur {1} mm":"vītņots caurums {0} – ieskrūvēšanas dziļums tikai {1} mm",
"Gewindebohrung {0}, Einschraubtiefe {1} mm":"vītņots caurums {0}, ieskrūvēšanas dziļums {1} mm",
"Gewindebohrung: gebohrt wird das Kernloch; das Gewinde erscheint als Gewindedarstellung am Modell und mit seinem Namen in der Zeichnung.":"Vītnes caurums: tiek izurbts serdes caurums; vītne parādās kā vītnes attēlojums modelī un ar savu nosaukumu rasējumā.",
"Gewindebohrungen":"Vītņcaurumi",
