"Glatter Zylinder":"Gluds cilindrs",
"Gleich":"Vienāds",
"Gleich gerichtet (statt gegenüber)":"Vienāds virziens (nevis pretējs)",
"Gleiche Durchmesser ergeben ein Rohr, verschiedene einen Kegelstumpf. Die Abwicklung wird auf der neutralen Faser gerechnet (Innenfläche + K-Faktor × Blechdicke); beim Runden liegt sie näher an der Blechmitte als beim Abkanten – üblich ist ein K-Faktor von 0,45 bis 0,5. Mit einer Blechregel gelten deren Dicke und K-Faktor. Der Nahtspalt bleibt am größeren Durchmesser offen (0 = stumpf gestoßen, im Körper dann ein Schlitz von 0,01 mm).":"Vienādi diametri dod cauruli, atšķirīgi – nošķeltu konusu. Izklājumu aprēķina uz neitrālās šķiedras (iekšējā virsma + K-faktors × skārda biezums); velmējot tā atrodas tuvāk skārda vidum nekā liecot – parasti K-faktors ir no 0,45 līdz 0,5. Ar skārda likumu spēkā ir tā biezums un K-faktors. Šuves sprauga paliek atvērta pie lielākā diametra (0 = sadurot, ķermenī tad 0,01 mm sprauga).",
