"Je Operation zwei Q-Parameter am Programmanfang: der erste verschiebt die Tiefe (DL, + = weniger tief), der zweite das seitliche Aufmaß (DR, + = mehr Aufmaß; wirkt nur bei Radiuskorrektur an der Steuerung RL/RR). An der Maschine eine Zahl ändern statt Sätze suchen.":"Katrai operācijai divi Q parametri programmas sākumā: pirmais nobīda dziļumu (DL, + = seklāk), otrais sānu piedevu (DR, + = lielāka piedeva; darbojas tikai ar rādiusa korekciju vadības sistēmā RL/RR). Uz mašīnas mainiet vienu skaitli, nevis meklējiet blokus.",
"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"No katras skices pirmā līkne – atvērta vai slēgta. Līknes tiek savienotas ar apvalku (virsma bez biezuma).",
"Je Tafel eine Datei. Die Bahn läuft um die halbe Schnittfuge (beim Fräsen den halben Fräser) neben dem Umriss im Abfall; Ausschnitte kommen vor dem Umriss ihres Teils, jede Kontur beginnt mit einem Anschnitt aus dem Abfall. Kiemenschlitze werden auf ihrer Linie geschnitten. Haltestege: so viele Stellen je Umriss bleiben stehen (Laser, Plasma, Wasserstrahl: der Strahl setzt dort aus; Fräsen: der Fräser hebt auf halbe Blechdicke), Umrisse unter 40 mm Länge bekommen keine. „Steuerung“ legt fest, womit der Strahl ein- und ausgeschaltet wird; die Einstechzeit steht als G4 im Programm, außer die Steuerung sticht selbst ein. Nullpunkt ist die linke untere Ecke der Tafel, beim Fräsen Z0 die Blechoberseite. Das Programm vor dem Einsatz an der Maschine oder in einem NC-Simulator prüfen.":"Viens fails uz loksni. Trajektorija iet atgriezumos blakus kontūrai griezuma platuma pusē (frēzējot – frēzes pusē) attālumā; izgriezumi tiek veikti pirms savas detaļas kontūras, un katra kontūra sākas ar iegriešanos no atgriezumiem. Žalūzijas tiek griezētas pa savu līniju. Turēšanas tiltiņi: tik daudz vietu uz kontūru paliek negrieztas (lāzers, plazma, ūdens strūkla: starš tur izslēdzas; frēzēšana: frēze paceļas līdz pusei skārda biezuma); kontūras, kas īsākas par 40 mm, tiltiņus nesaņem. „Vadība“ nosaka, ar ko starš tiek ieslēgts un izslēgts; caurduršanas laiks programmā ir ierakstīts kā G4, ja vien vadība pati neizdur. Nullpunkts ir loksnes apakšējais kreisais stūris, frēzējot Z0 ir skārda augšpuse. Pirms lietošanas programmu pārbaudiet iekārtā vai NC simulatorā.",
"Je Werkzeug alle Teile (weniger Werkzeugwechsel)":"Visas detaļas ar katru instrumentu (mazāk instrumentu maiņu)",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"Katra ass atsevišķi: noklikšķiniet uz malas, stūra, skaldnes vai cauruma. Nenoteiktās asis tiek ņemtas no sagataves punkta.",
"Jede Bohrung wird mit ihren Koordinaten einzeln angefahren (X/Y je Bohrung) – kein Lochkreis- oder Rastermuster.":"Katrs urbums tiek sasniegts atsevišķi ar savām koordinātām (X/Y katram urbumam) – bez urbumu apļa vai režģa raksta.",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"Katra operācija kā apakšprogramma (LBL) programmas beigās, izsaukums ar CALL LBL",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"Katrs skices aplis ir cauruma centrs. Urbj pretēji skices normālei (materiālā).",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"Katrs skices aplis tiek atkārtots, pagriežot ap centru (skices koordinātēs) – aplis soļa riņķa rādiusa attālumā dod urbumu riņķi.",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"Katrs skices aplis kļūst par režģi: skices atstarpes pa X un Y (arī negatīvas).",
"Jeder sichtbare Körper wird ein Glied mit Netz (STL, in Metern), Masse und Trägheit, jedes Gelenk ein Gelenk mit Achse und Grenzen. Die jetzige Stellung ist die Nullstellung. Mit einem Paketnamen stehen die Netze im URDF als package://Name/meshes/…, sonst als relativer Pfad.":"Katrs redzamais ķermenis kļūst par posmu ar tīklu (STL, metros), masu un inerci, katrs savienojums – par savienojumu ar asi un robežām. Pašreizējā poza ir nulles poza. Ar pakotnes nosaukumu tīkli URDF ir norādīti kā package://Name/meshes/…, citādi kā relatīvs ceļš.",
"Jedes # im Skizzentext wird durch die Nummer ersetzt, mit Nullen aufgefüllt (SN-#### → SN-{0}). Bei mehreren Teilen in einer Aufspannung bekommt jedes Teil die nächste Nummer: {1}{2}.":"Katru # skices tekstā aizstāj ar numuru, papildinātu ar nullēm (SN-#### → SN-{0}). Ja vienā iestiprinājumā ir vairākas detaļas, katra saņem nākamo numuru: {1}{2}.",
"Jedes Teil hat seinen eigenen Nullpunkt in der Steuerung (G54, G55 … bzw. Bezugspunkt-Nummer in der Tabelle – Heidenhain Zyklus 247). Alle Nullpunkte vorher an der Maschine setzen.":"Katrai detaļai vadības sistēmā ir savs nullpunkts (G54, G55 … vai atskaites punkta numurs tabulā – Heidenhain cikls 247). Visus nullpunktus iepriekš iestatiet uz mašīnas.",
"Jedes eigene Maß und jeder Toleranzrahmen bekommt eine Nummer in einem Kreis. Die Liste enthält Nennmaß, Toleranz, Höchst- und Mindestmaß und Felder für den Istwert. Maße ohne eigene Toleranz bekommen die Allgemeintoleranz.":"Katrs izmērs un katrs pielaides rāmis saņem numuru aplī. Sarakstā ir nominālizmērs, pielaide, maksimālais un minimālais izmērs un lauki faktiskajai vērtībai. Izmēri bez savas pielaides saņem vispārējo pielaidi.",
"Jetzigen Stand festhalten":"Saglabāt pašreizējo stāvokli",
"Jetzt einen Punkt auf dem zweiten Schenkel.":"Tagad punkts uz otrās malas.",
"Jetzt festhalten":"Saglabāt tagad",
"Jetzt jede Richtung einmal bis zum Anschlag: schieben, ziehen, drücken, kippen, drehen (10 s) …":"Tagad katrā virzienā vienu reizi līdz galam: bīdīt, vilkt, spiest, sasvērt, griezt (10 s) …",
