"Kante projiziert":"Mala projicēta",
"Kante {0} (Bogen R{1}, {2} mm)":"Mala {0} (loks R{1}, {2} mm)",
"Kante {0} (Kreis R{1}, {2} mm)":"Mala {0} (riņķa līnija R{1}, {2} mm)",
"Kante {0} ({1} mm)":"Mala {0} ({1} mm)",
"Kante {0} ist zu kurz für eine Lasche":"Mala {0} ir par īsu atlokam",
"Kante {0}: Biegewinkel über 180° ist nicht herstellbar.":"Mala {0}: lielāku par 180° locījuma leņķi izgatavot nav iespējams.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestaucht (Faltengefahr); der Zuschnitt ist dort eine Näherung.":"Mala {0}: atloks uz liektas malas – tā mala formēšanas laikā tiek saspiesta par {1} % (krokošanās risks); izklājums šeit ir tuvinājums.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestreckt (Rissgefahr); der Zuschnitt ist dort eine Näherung.":"Mala {0}: atloks uz liektas malas – tā mala formēšanas laikā tiek izstiepta par {1} % (plaisāšanas risks); izklājums šeit ir tuvinājums.",
"Kante {0}: das Laschenmaß {1} mm ist kleiner als die Biegung ({2} mm)":"Mala {0}: atloka izmērs {1} mm ir mazāks par locījumu ({2} mm)",
"Kante {0}: der Bogen ist zu eng für diese Lasche":"Mala {0}: loks ir pārāk šaurs šim atlokam",
"Kante {0}: die Abstände lassen keine Lasche übrig.":"Mala {0}: atstarpes neatstāj atloku.",
"Kante {0}: die Lasche kreuzt eine Biegelinie – mit „Abstand Anfang / Ende“ vor der Biegung enden lassen":"Mala {0}: atloks krusto liekuma līniju – ļaujiet tam beigties pirms liekuma, izmantojot „Atstarpe sākums / beigas“",
"Kante {0}: die Lasche liegt in einer Biegezone":"Mala {0}: atloks atrodas liekuma zonā",
"Kante {0}: ein Ausschnitt gehört zu einer Lasche, die es nicht gibt.":"Mala {0}: izgriezums pieder atlokam, kura nepastāv.",
"Kante {0}: ein Ausschnitt in der Lasche liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Mala {0}: izgriezums atlokā atrodas {1} mm no locījuma (mazāk nekā 2 × skārda biezums) – locīšanas laikā tas deformējas.",
"Kante {0}: ein Ausschnitt liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Mala {0}: izgriezums atrodas {1} mm no locījuma (mazāk par 2 × skārda biezums) – locīšanas laikā tas deformēsies.",
"Kante {0}: ein Ausschnitt ragt über die Lasche hinaus.":"Mala {0}: izgriezums sniedzas ārpus atloka.",
"Kante {0}{1}: Lasche {2} mm ist kürzer als 2 × Blechdicke – auf der Abkantpresse kaum zu biegen.":"Mala {0}{1}: atloks {2} mm ir īsāks par 2 × skārda biezums – uz lokpreses gandrīz nav saliecams.",
"Kante {0}{1}: Saum {2} mm ist kürzer als 4 × Blechdicke – er lässt sich schlecht zudrücken.":"Mala {0}{1}: locījums {2} mm ir īsāks par 4 × skārda biezums – to grūti saspiest.",
"Kante {0}{1}: geschlossener Saum (Innenradius {2} mm) – wird in zwei Hüben gebogen und zugedrückt; harte Werkstoffe reißen dabei an der Außenseite.":"Mala {0}{1}: aizvērts locījums (iekšējais rādiuss {2} mm) – tiek liekts divos gājienos un saspiests; cieti materiāli pie tam plīst ārpusē.",
"Kanten":"Malas",
"Kanten (Geraden deckungsgleich, Kreise mittig)":"Malas (taisnes sakrīt, apļi koncentriski)",
"Kanten anklicken (erneut klicken entfernt).":"Noklikšķiniet uz malām (atkārtots klikšķis noņem).",
"Kanten anklicken zum Hinzufügen oder Entfernen – das Ergebnis erscheint gleich im Modell. Kanten, die vor dem Befehl angeklickt wurden, sind schon gewählt. Eingabe = OK.":"Noklikšķiniet uz malām, lai tās pievienotu vai noņemtu – rezultāts uzreiz parādās modelī. Malas, uz kurām noklikšķināts pirms komandas, jau ir izvēlētas. Enter = Labi.",
"Kanten im Modell anklicken (erneut klicken entfernt)":"Noklikšķiniet uz modeļa malām (atkārtots klikšķis noņem)",
"Kanten wählen":"Izvēlēties malas",
"Kanten wählen, die einen geschlossenen Rand bilden":"Izvēlieties šķautnes, kas veido slēgtu malu",
"Kantenglättung":"Malu izlīdzināšana",
