"Lasche an Lasche: Winkel + biegt in dieselbe Richtung weiter (U-Profil, Falz mit 180°), − in die Gegenrichtung (Z-Stufe, Hutprofil). Saum: der Rand der Lasche wird um 180° auf sich selbst zurückgelegt – offen mit einem Spalt von einer Blechdicke, geschlossen flach zugedrückt; mit − 180° liegt er auf der anderen Seite. Das Feld R ist der Innenradius nur dieser Biegung (leer = wie beim Blech). Für einen Saum direkt an der Plattenkante die Lasche selbst auf 180° stellen. Kröpfung: zwei Biegungen gegeneinander (− 45° und + 45°) – der Rand läuft parallel versetzt weiter; Versatz über die Länge des schrägen Stücks und die Winkel.":"Atloks uz atloka: leņķis + liec tālāk tajā pašā virzienā (U profils, vīle 180°), − pretējā virzienā (Z pakāpiens, cepures profils). Malas locījums: atloka mala tiek atlocīta par 180° uz sevi – atvērts ar spraugu viena skārda biezuma apmērā, aizvērts saspiests plakans; ar − 180° tas atrodas otrā pusē. Lauks R ir tikai šīs lieces iekšējais rādiuss (tukšs = kā skārdam). Malas locījumam tieši uz plātnes malas pašu atloku iestatiet uz 180°. Pakāpveida liece: divas lieces pretī viena otrai (− 45° un + 45°) – mala turpinās paralēli nobīdīta; nobīde izriet no slīpā posma garuma un leņķiem.",
"Lasche {0}":"Atloks {0}",
