"Mehrachsen (nicht verfügbar)":"Daudzasu (nav pieejama)",
"Mehrere Schlichtdurchgänge":"Vairāki apdares gājieni",
"Mehrere Schrupp- oder Schlichtdurchgänge gibt es nur als Bahn":"Vairāki rupjās vai tīrās apstrādes gājieni ir pieejami tikai kā trajektorija",
"Mehrere Teile in einer Aufspannung":"Vairākas detaļas vienā iestiprinājumā",
"Mehrere Zustellungen und Leerdurchgang gibt es nur als Bahn":"Vairāki padevumi un tukšais gājiens ir pieejami tikai kā trajektorija",
"Mehrere aneinanderhängende Kanten zählen als eine Strecke: Der Radius läuft vom Anfang der Kette bis zu ihrem Ende, Stützpunkte gelten in % der ganzen Kettenlänge. Das rechnet der große Geometriekern.":"Vairākas savienotas malas tiek uzskatītas par vienu posmu: rādiuss iet no ķēdes sākuma līdz tās beigām, atbalsta punkti tiek doti % no visa ķēdes garuma. To aprēķina pilnais ģeometrijas kodols.",
"Mehrfachaufspannung":"Vairākas detaļas",
"Mehrfachaufspannung: Nullpunkt von Teil {0} gibt es an dieser Steuerung nicht – nur ein Teil ausgegeben":"Vairākas detaļas: šai vadības sistēmai nav nullpunkta {0}. detaļai – izvadīta tikai viena detaļa",
"Mehrfachaufspannung: Nullpunktverschiebung gibt es in diesem Postprozessor nicht – „Eigener Nullpunkt je Teil“ wählen; nur ein Teil ausgegeben":"Vairākas detaļas: šim postprocesoram nav nullpunkta nobīdes – izvēlieties „Savs nullpunkts katrai detaļai“; izvadīta tikai viena detaļa",
"Meine Designs · {0}":"Mani dizaini · {0}",
"Meine Werkzeuge":"Mani instrumenti",
"Meldet Bahnen, die tiefer schneiden als das Modell an dieser Stelle (Schaft-, Plan-, Kugel- und Torusfräser, Fasenfräser und Bohrer mit ihrem Kegel; 3-Achs-Bewegungen). Ein Schnitt, der nicht im Modell steht – Gravur, Eckenfreistich, Tasche nur aus einer Skizze – wird ebenfalls gemeldet.":"Ziņo par trajektorijām, kas šajā vietā griež dziļāk nekā modelis (kāta, plakanās, lodveida un toru frēzes, nošķēlumu frēzes un urbji ar savu konusu; 3 asu kustības). Tiek ziņots arī par griezumu, kura modelī nav – gravējums, stūra atslogojums, kabata tikai no skices.",
"Meldung auf dem Bildschirm der Steuerung: Fanuc und LinuxCNC als (MSG, …), Sinumerik als MSG(\"…\"), sonst als Kommentar.":"Ziņojums vadības ekrānā: Fanuc un LinuxCNC kā (MSG, …), Sinumerik kā MSG(\"…\"), citādi kā komentārs.",
