"Noch kein Körper gewählt – bis dahin gilt die relative Quadergröße.":"Ķermenis vēl nav izvēlēts – līdz tam ir spēkā relatīvais kvadra izmērs.",
"Noch kein Körper vorhanden – erst in KONSTRUKTION modellieren.":"Ķermeņa vēl nav — vispirms izveidojiet modeli sadaļā KONSTRUĒŠANA.",
"Noch kein Profil gewählt – Bereiche der Skizze anklicken.":"Profils vēl nav izvēlēts – noklikšķiniet uz skices apgabaliem.",
"Noch kein Skript – eine .py-Datei oder einen Ordner laden.":"Vēl nav skripta – ielādējiet .py failu vai mapi.",
"Noch kein Wiederherstellungspunkt – der erste entsteht, sobald sich der Entwurf ändert und die eingestellte Zeit vergangen ist.":"Atjaunošanas punkta vēl nav – pirmais tiks izveidots, kad projekts mainīsies un iestatītais laiks būs pagājis.",
"Noch kein Zusatzmodul – einen Ordner mit Zusatzmodul laden.":"Vēl nav papildmoduļa – ielādējiet mapi ar papildmoduli.",
"Noch keine Designs gespeichert.":"Vēl nav saglabātu dizainu.",
"Noch keine Kommentare. Mit + Notizen zum Design festhalten.":"Vēl nav komentāru. Ar + pievienojiet piezīmes par dizainu.",
"Noch keine Operation":"Operāciju vēl nav",
"Noch keine Vorlagen. Eine Vorlage speichert Strategien mit allen Einstellungen (Werkzeug, Schnittdaten, Höhen, Durchgänge, Verknüpfung) zum Wiederverwenden in anderen Setups und Designs.":"Sablonu vēl nav. Sablons saglabā stratēģijas ar visiem iestatījumiem (instruments, griešanas dati, augstumi, gājieni, saistība) atkārtotai izmantošanai citos uzstādījumos un dizainos.",
"Noch keine Werkzeuge im Dokument.":"Dokumentā vēl nav instrumentu.",
"Noch keine. Geometrie wählen und oben unter ABHÄNGIGKEITEN ein Werkzeug anklicken.":"Vēl nav. Izvēlieties ģeometriju un augšā sadaļā IEROBEŽOJUMI noklikšķiniet uz rīka.",
