"Schruppt simultan 4-achsig von außen nach innen: je Zustellung eine Spirale um die A-Achse (abwechselnd in +X und −X), nie tiefer als das Teil plus Aufmaß. Mit Schaft- oder Kugelfräser.":"Veic rupjapstrādi vienlaikus 4 asīs no ārpuses uz iekšu: katrā padevē viena spirāle ap A asi (pārmaiņus +X un −X virzienā), nekad dziļāk par detaļu plus piedevu. Ar kāta vai lodveida frēzi.",
