"Teil 1 liegt normalerweise auf dem Nullpunkt (0, 0, 0). Die anderen werden mit einer Nullpunktverschiebung angefahren (Heidenhain Zyklus 7, Fanuc/LinuxCNC G52, Sinumerik TRANS). Vor jedem Wechsel geht das Werkzeug auf die sichere Höhe.":"1. detaļa parasti atrodas nullpunktā (0, 0, 0). Pārējām pieiet ar nullpunkta nobīdi (Heidenhain cikls 7, Fanuc/LinuxCNC G52, Sinumerik TRANS). Pirms katras maiņas instruments pāriet drošajā augstumā.",
