"Verschraubung: Scheiben und Mutter kommen mit der Schraube in einem Zug an jede angeklickte Bohrung. Die Klemmdicke ist die Länge der Bohrung – durch mehrere Teile hindurch, wenn ihre Bohrungen fluchten und aneinanderstoßen. Mit Mutter wird die kürzeste Vorzugslänge vorgeschlagen, bei der die Schraube zwei Gewindegänge aus der Mutter ragt.":"Skrūvsavienojums: paplāksnes un uzgrieznis tiek novietoti kopā ar skrūvi vienā reizē uz katra noklikšķinātā cauruma. Saspiešanas biezums ir cauruma garums – cauri vairākām detaļām, ja to caurumi atrodas uz vienas ass un saskaras. Ar uzgriezni tiek piedāvāts īsākais ieteicamais garums, pie kura skrūve izvirzās no uzgriežņa par diviem vītnes gājieniem.",
