"Wert":"Vērtība",
"Werte vom Werkzeug übernehmen":"Pārņemt vērtības no instrumenta",
"Wickelt die Skizzenkurven auf den Zylinder: X bleibt X, der Abstand quer zur Achse wird zum Bogen auf dem Abwicklungs-Ø (Drehung A). Die Skizze muss parallel zur A-Achse liegen, z. B. auf einer Tangentialebene. Gefräst wird in fester Tiefe unter der Teiloberfläche – für Gravuren, Schriften und Nuten rund um das Teil.":"Uztin skices līknes uz cilindra: X paliek X, attālums šķērsām asij kļūst par loku uz attīšanas Ø (rotācija A). Skicei jābūt paralēlai A asij, piem., pieskares plaknē. Frēzē nemainīgā dziļumā zem detaļas virsmas – gravējumiem, uzrakstiem un rievām ap detaļu.",
"Wie 3D-Kontur, aber das Werkzeug fährt ohne Absätze kontinuierlich nach unten – keine Eintauchmarken an steilen Wänden.":"Tāpat kā 3D kontūra, bet instruments virzās uz leju nepārtraukti, bez pakāpieniem – nav iegrimšanas pēdu uz stāvām sienām.",
"Wie Einfahrt":"Tāpat kā pieeja",
"Wie ausgewählt":"Kā izvēlēts",
"Wie die Ansicht":"Tāpat kā skatā",
"Wie die Ansicht (alle Dreiecke)":"Kā skatā (visi trijstūri)",
"Wie fein Körper für STL, 3MF und den Slicer in Dreiecke zerlegt werden: Abweichung von der wahren Fläche als Anteil der Körpergröße. Netze bleiben, wie sie sind.":"Cik smalki ķermeņi STL, 3MF un Slicer tiek sadalīti trīsstūros: novirze no patiesās virsmas kā ķermeņa izmēra daļa. Tīkli paliek tādi, kādi ir.",
"Wie fein Zylinder, Kugeln und Rundungen in der Ansicht aus Dreiecken bestehen. Feiner sieht runder aus, rechnet bei großen Modellen aber länger. Der Export hat eine eigene Einstellung (3D-Druck).":"Cik smalki cilindri, lodes un noapaļojumi skatā sastāv no trijstūriem. Smalkāks izskatās apaļāks, bet lieliem modeļiem aprēķins ilgst ilgāk. Eksportam ir sava iestatījums (3D drukāšana).",
"Wie im System":"Kā sistēmā",
"Wie lange die Schneide schneiden darf, bevor sie getauscht wird. Das Fenster „Bearbeitungszeit“ rechnet daraus, wie viele Teile noch möglich sind.":"Cik ilgi griezējmala drīkst griezt, pirms to nomaina. Logs „Apstrādes laiks” no tā aprēķina, cik detaļu vēl ir iespējams izgatavot.",
"Wie oben gewählt":"Kā izvēlēts iepriekš",
"Wie viel Platz um das Modell bleibt, wenn die Ansicht eingepasst wird":"Cik daudz vietas paliek ap modeli, kad skats tiek ietilpināts",
"Wie viele Schritte Strg+Z zurückgehen kann":"Cik soļu atpakaļ var atsaukt ar Ctrl+Z",
