"Zungen stehen am freien Ende der Lasche über und kommen in den Zuschnitt. „Schlitze als Skizze“ legt die passenden Schlitze dort an, wo die Zungen stehen – je Ebene eine Skizze, jeder Schlitz ringsum um das Spiel größer als die Zunge. In dieser Skizze den Umriss des Gegenstücks zeichnen und daraus ein Blech oder eine Extrusion machen: die Schlitze werden Ausschnitte. Das Gegenstück liegt auf den Laschenenden auf; die Zungenlänge ist üblich gleich seiner Dicke.":"Mēlītes izvirzās atloka brīvajā galā un iekļaujas sagatavē. „Spraugas kā skice“ izveido atbilstošās spraugas tur, kur atrodas mēlītes – pa vienai skicei katrā plaknē, katra sprauga visapkārt ir par atstarpi lielāka nekā mēlīte. Šajā skicē uzzīmējiet pretdetaļas kontūru un izveidojiet no tās skārdu vai izspiedumu: spraugas kļūst par izgriezumiem. Pretdetaļa balstās uz atloku galiem; mēlītes garums parasti ir vienāds ar tās biezumu.",
