"Zwischen zwei Schnitten hebt das Werkzeug nur so weit ab, wie das Material auf dem Weg es verlangt (Rohteil abzüglich allem, was dieses Setup bis dahin gefräst hat) plus Sicherheitsabstand – und beginnt den Vorschub erst dort.{0}{1}":"Starp diviem griezumiem instruments paceļas tikai tik augstu, cik to prasa materiāls ceļā (sagatave mīnus viss, ko šī uzstādīšana līdz tam izfrēzējusi) plus drošības attālums – un sāk padevi tikai tur.{0}{1}",
